package business.service;

import business.dao.CategoryDAO;
import entity.Category;

import java.util.List;

public class CategoryService {

    CategoryDAO dao = new CategoryDAO();

    public void add(Category c) throws Exception {
        dao.add(c);
    }

    public void show() throws Exception {
        List<Category> list = dao.getAll();

        for (Category c : list) {
            System.out.println(c.getId() + " - " + c.getName());
        }
    }
}

package business.service;

import business.dao.CategoryDAO;
import entity.Category;

import java.util.List;

/**
 * CategoryService - Lớp dịch vụ quản lý danh mục
 * Xử lý business logic và validation cho danh mục sản phẩm
 */
public class CategoryService {

    CategoryDAO dao = new CategoryDAO();

    /**
     * Thêm danh mục mới
     * @param c Đối tượng Category chứa thông tin danh mục
     * @throws Exception Nếu dữ liệu không hợp lệ hoặc có lỗi database
     */
    public void add(Category c) throws Exception {
        // Kiểm tra tên danh mục
        if (c.getName() == null || c.getName().trim().isEmpty()) {
            throw new Exception("Tên danh mục không được để trống!");
        }

        if (c.getName().length() < 2 || c.getName().length() > 100) {
            throw new Exception("Tên danh mục phải từ 2 đến 100 ký tự!");
        }

        // Kiểm tra mô tả
        if (c.getDescription() != null && c.getDescription().length() > 500) {
            throw new Exception("Mô tả danh mục không được vượt quá 500 ký tự!");
        }

        dao.add(c);
    }

    /**
     * Lấy tất cả danh mục
     * @return Danh sách tất cả danh mục
     * @throws Exception Nếu có lỗi database
     */
    public List<Category> getAll() throws Exception {
        return dao.getAll();
    }

    /**
     * Lấy danh mục theo ID
     * @param id ID của danh mục
     * @return Đối tượng Category hoặc null nếu không tìm thấy
     * @throws Exception Nếu có lỗi database
     */
    public Category getById(int id) throws Exception {
        if (id <= 0) {
            throw new Exception("ID danh mục phải lớn hơn 0!");
        }
        return dao.getById(id);
    }

    /**
     * Cập nhật danh mục
     * @param c Đối tượng Category chứa thông tin cần cập nhật
     * @throws Exception Nếu dữ liệu không hợp lệ hoặc có lỗi database
     */
    public void update(Category c) throws Exception {
        if (c.getId() <= 0) {
            throw new Exception("ID danh mục không hợp lệ!");
        }

        if (c.getName() == null || c.getName().trim().isEmpty()) {
            throw new Exception("Tên danh mục không được để trống!");
        }

        if (c.getName().length() < 2 || c.getName().length() > 100) {
            throw new Exception("Tên danh mục phải từ 2 đến 100 ký tự!");
        }

        dao.update(c);
    }

    /**
     * Xóa danh mục theo ID
     * @param id ID của danh mục cần xóa
     * @throws Exception Nếu có lỗi database
     */
    public void delete(int id) throws Exception {
        if (id <= 0) {
            throw new Exception("ID danh mục phải lớn hơn 0!");
        }
        dao.delete(id);
    }

    /**
     * Hiển thị tất cả danh mục dưới dạng bảng
     * @throws Exception Nếu có lỗi database
     */
    public void show() throws Exception {
        List<Category> list = getAll();

        if (list.isEmpty()) {
            System.out.println(" Không có danh mục nào.");
            return;
        }

        System.out.println("\n========== DANH SÁCH DANH MỤC ==========");
        System.out.println(String.format("%-5s | %-30s | %-40s", "ID", "Tên danh mục", "Mô tả"));
        System.out.println("-".repeat(80));

        for (Category c : list) {
            String desc = c.getDescription() != null ? c.getDescription() : "";
            if (desc.length() > 35) {
                desc = desc.substring(0, 35) + "...";
            }
            System.out.println(String.format("%-5d | %-30s | %-40s", c.getId(), c.getName(), desc));
        }

        System.out.println("\n Tổng cộng: " + list.size() + " danh mục");
    }
}

import business.dao.ProductDAO;
import business.dao.UserDAO;
import business.dao.CategoryDAO;
import business.service.AuthService;
import business.service.ProductService;
import business.service.CategoryService;
import entity.User;
import entity.Product;
import entity.Category;

import java.util.*;

public class Main {

    static User currentUser = null;

    public static void main(String[] args) throws Exception {

        Scanner sc = new Scanner(System.in);
        UserDAO userDAO = new UserDAO();
        ProductDAO productDAO = new ProductDAO();

        while (true) {
            System.out.println("\n===== MENU =====");
            System.out.println("1. Đăng ký");
            System.out.println("2. Đăng nhập");
            System.out.println("0. Thoát");

            int choice = Integer.parseInt(sc.nextLine());

            switch (choice) {

                case 1:
                    User u = new User();

                    System.out.print("Tên: ");
                    u.setName(sc.nextLine());

                    System.out.print("Email: ");
                    u.setEmail(sc.nextLine());

                    System.out.print("Pass: ");
                    u.setPassword(sc.nextLine());

                    userDAO.register(u);
                    break;

                case 2:
                    System.out.print("Email: ");
                    String email = sc.nextLine();

                    System.out.print("Pass: ");
                    String pass = sc.nextLine();

                    currentUser = userDAO.login(email, pass);

                    if (currentUser != null) {
                        System.out.println("Login OK (" + currentUser.getRole() + ")");

                        if (currentUser.getRole().equals("ADMIN")) {
                            menuAdmin(sc, productDAO);
                        } else {
                            menuCustomer(sc, productDAO);
                        }
                    } else {
                        System.out.println("Sai!");
                    }
                    break;

                case 0:
                    return;
            }
        }
    }

    // ================= ADMIN MENU =================
    public static void menuAdmin(Scanner sc, ProductDAO productDAO) throws Exception {
        ProductService productService = new ProductService();
        CategoryService categoryService = new CategoryService();

        while (true) {
            System.out.println("\n========== MENU QUẢN TRỊ ADMIN ==========");
            System.out.println(" QUẢN LÝ SẢN PHẨM:");
            System.out.println("  1. ➕ Thêm sản phẩm");
            System.out.println("  2.  Hiển thị tất cả sản phẩm");
            System.out.println("  3.  Tìm kiếm sản phẩm");
            System.out.println("  4. ✏️  Cập nhật sản phẩm");
            System.out.println("  5. ️  Xóa sản phẩm");
            System.out.println(" QUẢN LÝ DANH MỤC:");
            System.out.println("  6. ➕ Thêm danh mục");
            System.out.println("  7.  Hiển thị tất cả danh mục");
            System.out.println("  8. ✏️  Cập nhật danh mục");
            System.out.println("  9. ️  Xóa danh mục");
            System.out.println("━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━");
            System.out.println("  10.  Đăng xuất");
            System.out.println("  0.  Thoát ứng dụng");
            System.out.print("Chọn: ");

            String choice = sc.nextLine().trim();

            try {
                switch (choice) {
                    case "1":
                        addProductAdmin(sc, productService);
                        break;
                    case "2":
                        productService.show();
                        break;
                    case "3":
                        searchProductAdmin(sc, productService);
                        break;
                    case "4":
                        updateProductAdmin(sc, productService);
                        break;
                    case "5":
                        deleteProductAdmin(sc, productService);
                        break;
                    case "6":
                        addCategoryAdmin(sc, categoryService);
                        break;
                    case "7":
                        categoryService.show();
                        break;
                    case "8":
                        updateCategoryAdmin(sc, categoryService);
                        break;
                    case "9":
                        deleteCategoryAdmin(sc, categoryService);
                        break;
                    case "10":
                        System.out.println("✅ Đã đăng xuất thành công!");
                        return;
                    case "0":
                        System.out.println("Cảm ơn đã sử dụng dịch vụ. Tạm biệt!");
                        System.exit(0);
                    default:
                        System.out.println("❌ Lựa chọn không hợp lệ!");
                }
            } catch (Exception e) {
                System.out.println("❌ Lỗi: " + e.getMessage());
            }
        }
    }

    // ================= THÊM SẢN PHẨM (ADMIN) =================
    public static void addProductAdmin(Scanner sc, ProductService productService) throws Exception {
        System.out.println("\n========== THÊM SẢN PHẨM MỚI ==========");

        Product p = new Product();

        while (true) {
            System.out.print("Tên sản phẩm: ");
            String name = sc.nextLine().trim();
            if (!name.isEmpty()) {
                p.setName(name);
                break;
            }
            System.out.println("❌ Tên sản phẩm không được để trống!");
        }

        System.out.print("Nhãn hiệu: ");
        String brand = sc.nextLine().trim();
        if (!brand.isEmpty()) p.setBrand(brand);

        System.out.print("Dung lượng: ");
        String storage = sc.nextLine().trim();
        if (!storage.isEmpty()) p.setStorage(storage);

        System.out.print("Màu sắc: ");
        String color = sc.nextLine().trim();
        if (!color.isEmpty()) p.setColor(color);

        while (true) {
            System.out.print("Giá (VND): ");
            try {
                double price = Double.parseDouble(sc.nextLine().trim());
                p.setPrice(price);
                break;
            } catch (NumberFormatException e) {
                System.out.println("❌ Vui lòng nhập số hợp lệ!");
            }
        }

        while (true) {
            System.out.print("Số lượng kho: ");
            try {
                int stock = Integer.parseInt(sc.nextLine().trim());
                p.setStock(stock);
                break;
            } catch (NumberFormatException e) {
                System.out.println("❌ Vui lòng nhập số nguyên hợp lệ!");
            }
        }

        System.out.print("Mô tả sản phẩm: ");
        String desc = sc.nextLine().trim();
        if (!desc.isEmpty()) p.setDescription(desc);

        while (true) {
            System.out.print("ID danh mục: ");
            try {
                int catId = Integer.parseInt(sc.nextLine().trim());
                p.setCategoryId(catId);
                break;
            } catch (NumberFormatException e) {
                System.out.println("❌ Vui lòng nhập số nguyên hợp lệ!");
            }
        }

        try {
            productService.add(p);
            System.out.println("✅ Thêm sản phẩm thành công!");
        } catch (Exception e) {
            System.out.println("❌ Lỗi: " + e.getMessage());
        }
    }

    // ================= TÌM KIẾM SẢN PHẨM (ADMIN) =================
    public static void searchProductAdmin(Scanner sc, ProductService productService) throws Exception {
        System.out.print("\nNhập tên sản phẩm cần tìm: ");
        String key = sc.nextLine().trim();

        if (key.isEmpty()) {
            System.out.println("❌ Vui lòng nhập từ khóa!");
            return;
        }

        try {
            List<Product> results = productService.search(key);
            if (results.isEmpty()) {
                System.out.println(" Không tìm thấy sản phẩm nào!");
                return;
            }

            System.out.println("\n========== KẾT QUẢ TÌM KIẾM ==========");
            System.out.println(String.format("%-5s | %-25s | %-12s", "ID", "Tên", "Giá (VND)"));
            System.out.println("-".repeat(50));
            for (Product p : results) {
                System.out.println(String.format("%-5d | %-25s | %,12d",
                        p.getId(),
                        p.getName().length() > 25 ? p.getName().substring(0, 22) + "..." : p.getName(),
                        (long) p.getPrice()));
            }
            System.out.println("\n Tìm thấy: " + results.size() + " sản phẩm");
        } catch (Exception e) {
            System.out.println("❌ Lỗi: " + e.getMessage());
        }
    }

    // ================= CẬP NHẬT SẢN PHẨM (ADMIN) =================
    public static void updateProductAdmin(Scanner sc, ProductService productService) throws Exception {
        System.out.print("\nNhập ID sản phẩm cần cập nhật: ");
        try {
            int id = Integer.parseInt(sc.nextLine().trim());
            Product p = productService.getById(id);

            if (p == null) {
                System.out.println("❌ Sản phẩm không tồn tại!");
                return;
            }

            productService.displayDetails(p);

            System.out.print("\nTên sản phẩm (Enter nếu không thay đổi): ");
            String name = sc.nextLine().trim();
            if (!name.isEmpty()) p.setName(name);

            System.out.print("Giá (Enter nếu không thay đổi): ");
            String priceStr = sc.nextLine().trim();
            if (!priceStr.isEmpty()) {
                try {
                    p.setPrice(Double.parseDouble(priceStr));
                } catch (NumberFormatException e) {
                    System.out.println("⚠️  Giá không hợp lệ, giữ nguyên");
                }
            }

            System.out.print("Số lượng kho (Enter nếu không thay đổi): ");
            String stockStr = sc.nextLine().trim();
            if (!stockStr.isEmpty()) {
                try {
                    p.setStock(Integer.parseInt(stockStr));
                } catch (NumberFormatException e) {
                    System.out.println("⚠️  Kho không hợp lệ, giữ nguyên");
                }
            }

            try {
                productService.update(p);
                System.out.println("✅ Cập nhật sản phẩm thành công!");
            } catch (Exception e) {
                System.out.println("❌ Lỗi: " + e.getMessage());
            }
        } catch (NumberFormatException e) {
            System.out.println("❌ ID sản phẩm không hợp lệ!");
        }
    }

    // ================= XÓA SẢN PHẨM (ADMIN) =================
    public static void deleteProductAdmin(Scanner sc, ProductService productService) throws Exception {
        System.out.print("\nNhập ID sản phẩm cần xóa: ");
        try {
            int id = Integer.parseInt(sc.nextLine().trim());
            Product p = productService.getById(id);

            if (p == null) {
                System.out.println("❌ Sản phẩm không tồn tại!");
                return;
            }

            System.out.println("\n⚠️  BẠN SẮP XÓA:");
            productService.displayDetails(p);

            System.out.print("\nBạn chắc chắn muốn xóa? (yes/no): ");
            String confirm = sc.nextLine().trim().toLowerCase();

            if (confirm.equals("yes")) {
                try {
                    productService.delete(id);
                    System.out.println("✅ Xóa sản phẩm thành công!");
                } catch (Exception e) {
                    System.out.println("❌ Lỗi: " + e.getMessage());
                }
            } else {
                System.out.println("⏭️  Đã hủy xóa.");
            }
        } catch (NumberFormatException e) {
            System.out.println("❌ ID sản phẩm không hợp lệ!");
        }
    }

    // ================= THÊM DANH MỤC (ADMIN) =================
    public static void addCategoryAdmin(Scanner sc, CategoryService categoryService) throws Exception {
        System.out.println("\n========== THÊM DANH MỤC MỚI ==========");

        Category c = new Category();

        System.out.print("Tên danh mục: ");
        String name = sc.nextLine().trim();
        if (name.isEmpty()) {
            System.out.println("❌ Tên danh mục không được để trống!");
            return;
        }
        c.setName(name);

        System.out.print("Mô tả danh mục: ");
        String desc = sc.nextLine().trim();
        if (!desc.isEmpty()) c.setDescription(desc);

        try {
            categoryService.add(c);
            System.out.println("✅ Thêm danh mục thành công!");
        } catch (Exception e) {
            System.out.println("❌ Lỗi: " + e.getMessage());
        }
    }

    // ================= CẬP NHẬT DANH MỤC (ADMIN) =================
    public static void updateCategoryAdmin(Scanner sc, CategoryService categoryService) throws Exception {
        System.out.print("\nNhập ID danh mục cần cập nhật: ");
        try {
            int id = Integer.parseInt(sc.nextLine().trim());
            Category c = categoryService.getById(id);

            if (c == null) {
                System.out.println("❌ Danh mục không tồn tại!");
                return;
            }

            System.out.println("Danh mục hiện tại: " + c.getName() + " - " + c.getDescription());

            System.out.print("Tên danh mục mới (Enter nếu không thay đổi): ");
            String name = sc.nextLine().trim();
            if (!name.isEmpty()) c.setName(name);

            System.out.print("Mô tả (Enter nếu không thay đổi): ");
            String desc = sc.nextLine().trim();
            if (!desc.isEmpty()) c.setDescription(desc);

            try {
                categoryService.update(c);
                System.out.println("✅ Cập nhật danh mục thành công!");
            } catch (Exception e) {
                System.out.println("❌ Lỗi: " + e.getMessage());
            }
        } catch (NumberFormatException e) {
            System.out.println("❌ ID danh mục không hợp lệ!");
        }
    }

    // ================= XÓA DANH MỤC (ADMIN) =================
    public static void deleteCategoryAdmin(Scanner sc, CategoryService categoryService) throws Exception {
        System.out.print("\nNhập ID danh mục cần xóa: ");
        try {
            int id = Integer.parseInt(sc.nextLine().trim());
            Category c = categoryService.getById(id);

            if (c == null) {
                System.out.println("❌ Danh mục không tồn tại!");
                return;
            }

            System.out.println("\n⚠️  BẠN SẮP XÓA DANH MỤC: " + c.getName());
            System.out.print("Bạn chắc chắn muốn xóa? (yes/no): ");
            String confirm = sc.nextLine().trim().toLowerCase();

            if (confirm.equals("yes")) {
                try {
                    categoryService.delete(id);
                    System.out.println("✅ Xóa danh mục thành công!");
                } catch (Exception e) {
                    System.out.println("❌ Lỗi: " + e.getMessage());
                }
            } else {
                System.out.println("⏭️  Đã hủy xóa.");
            }
        } catch (NumberFormatException e) {
            System.out.println("❌ ID danh mục không hợp lệ!");
        }
    }

    // ================= CUSTOMER =================
    public static void menuCustomer(Scanner sc, ProductDAO dao) throws Exception {
        while (true) {
            System.out.println("\n========== CUSTOMER MENU ==========");
            System.out.println("1. Hiển thị sản phẩm");
            System.out.println("2. Tìm kiếm sản phẩm");
            System.out.println("3. Thêm vào giỏ hàng");
            System.out.println("4. Đặt hàng");
            System.out.println("5. Xem đơn hàng");
            System.out.println("6. Đăng xuất");
            System.out.println("0. Thoát");

            System.out.print("Chọn: ");
            int choice = Integer.parseInt(sc.nextLine());

            switch (choice) {

                case 1:
                    for (Product p : dao.getAll()) {
                        System.out.println(p.getName() + " - " + p.getPrice());
                    }
                    break;

                case 2:
                    System.out.print("Nhập tên: ");
                    String key = sc.nextLine();

                    for (Product p : dao.search(key)) {
                        System.out.println(p.getName());
                    }
                    break;

                case 3:
                    System.out.println("Thêm vào giỏ hàng (chưa implement)");
                    break;

                case 4:
                    System.out.println("Đặt hàng (chưa implement)");
                    break;

                case 5:
                    System.out.println("Xem đơn hàng (chưa implement)");
                    break;

                case 6:
                    return; // logout

                case 0:
                    System.exit(0);
            }
        }
    }
}

import business.dao.ProductDAO;
import business.dao.UserDAO;
import business.dao.CategoryDAO;
import business.service.AuthService;
import business.service.ProductService;
import business.service.CategoryService;
import entity.User;
import entity.Product;
import entity.Category;

import java.util.*;

public class Main {

    static User currentUser = null;

    public static void main(String[] args) throws Exception {

        Scanner sc = new Scanner(System.in);
        UserDAO userDAO = new UserDAO();
        ProductDAO productDAO = new ProductDAO();

        while (true) {
            System.out.println("\n===== MENU =====");
            System.out.println("1. Đăng ký");
            System.out.println("2. Đăng nhập");
            System.out.println("0. Thoát");

            int choice = Integer.parseInt(sc.nextLine());

            switch (choice) {

                case 1:
                    User u = new User();

                    System.out.print("Tên: ");
                    u.setName(sc.nextLine());

                    System.out.print("Email: ");
                    u.setEmail(sc.nextLine());

                    System.out.print("Pass: ");
                    u.setPassword(sc.nextLine());

                    userDAO.register(u);
                    break;

                case 2:
                    System.out.print("Email: ");
                    String email = sc.nextLine();

                    System.out.print("Pass: ");
                    String pass = sc.nextLine();

                    currentUser = userDAO.login(email, pass);

                    if (currentUser != null) {
                        System.out.println("Login OK (" + currentUser.getRole() + ")");

                        if (currentUser.getRole().equals("ADMIN")) {
                            menuAdmin(sc, productDAO);
                        } else {
                            menuCustomer(sc, productDAO);
                        }
                    } else {
                        System.out.println("Sai!");
                    }
                    break;

                case 0:
                    return;
            }
        }
    }

    // ================= ADMIN MAIN MENU =================
    public static void menuAdmin(Scanner sc, ProductDAO productDAO) throws Exception {
        while (true) {
            System.out.println("\n========== MENU QUẢN TRỊ ADMIN ==========");
            System.out.println("1.  Quản lý sản phẩm");
            System.out.println("2.  Quản lý danh mục");
            System.out.println("3.  Đăng xuất");
            System.out.println("0.  Thoát ứng dụng");
            System.out.print("Chọn: ");

            String choice = sc.nextLine().trim();

            switch (choice) {
                case "1":
                    menuProductManagement(sc);
                    break;
                case "2":
                    menuCategoryManagement(sc);
                    break;
                case "3":
                    System.out.println("✅ Đã đăng xuất thành công!");
                    return;
                case "0":
                    System.out.println("Cảm ơn đã sử dụng dịch vụ. Tạm biệt!");
                    System.exit(0);
                default:
                    System.out.println("❌ Lựa chọn không hợp lệ!");
            }
        }
    }

