    // ================= THÊM SẢN PHẨM (ADMIN) =================
    public static void addProductAdmin(Scanner sc, ProductService productService) throws Exception {
        System.out.println("\n========== THÊM SẢN PHẨM MỚI ==========");

        Product p = new Product();

        while (true) {
            System.out.print("Tên sản phẩm: ");
            String name = sc.nextLine().trim();
            if (!name.isEmpty()) {
                p.setName(name);
                break;
            }
            System.out.println("❌ Tên sản phẩm không được để trống!");
        }

        System.out.print("Nhãn hiệu: ");
        String brand = sc.nextLine().trim();
        if (!brand.isEmpty()) p.setBrand(brand);

        System.out.print("Dung lượng: ");
        String storage = sc.nextLine().trim();
        if (!storage.isEmpty()) p.setStorage(storage);

        System.out.print("Màu sắc: ");
        String color = sc.nextLine().trim();
        if (!color.isEmpty()) p.setColor(color);

        while (true) {
            System.out.print("Giá (VND): ");
            try {
                double price = Double.parseDouble(sc.nextLine().trim());
                p.setPrice(price);
                break;
            } catch (NumberFormatException e) {
                System.out.println("❌ Vui lòng nhập số hợp lệ!");
            }
        }

        while (true) {
            System.out.print("Số lượng kho: ");
            try {
                int stock = Integer.parseInt(sc.nextLine().trim());
                p.setStock(stock);
                break;
            } catch (NumberFormatException e) {
                System.out.println("❌ Vui lòng nhập số nguyên hợp lệ!");
            }
        }

        System.out.print("Mô tả sản phẩm: ");
        String desc = sc.nextLine().trim();
        if (!desc.isEmpty()) p.setDescription(desc);

        while (true) {
            System.out.print("ID danh mục: ");
            try {
                int catId = Integer.parseInt(sc.nextLine().trim());
                p.setCategoryId(catId);
                break;
            } catch (NumberFormatException e) {
                System.out.println("❌ Vui lòng nhập số nguyên hợp lệ!");
            }
        }

        try {
            productService.add(p);
            System.out.println("✅ Thêm sản phẩm thành công!");
        } catch (Exception e) {
            System.out.println("❌ Lỗi: " + e.getMessage());
        }
    }

    // ================= TÌM KIẾM SẢN PHẨM (ADMIN) =================
    public static void searchProductAdmin(Scanner sc, ProductService productService) throws Exception {
        System.out.print("\nNhập tên sản phẩm cần tìm: ");
        String key = sc.nextLine().trim();

        if (key.isEmpty()) {
            System.out.println("❌ Vui lòng nhập từ khóa!");
            return;
        }

        try {
            List<Product> results = productService.search(key);
            if (results.isEmpty()) {
                System.out.println(" Không tìm thấy sản phẩm nào!");
                return;
            }

            System.out.println("\n========== KẾT QUẢ TÌM KIẾM ==========");
            System.out.println(String.format("%-5s | %-25s | %-12s", "ID", "Tên", "Giá (VND)"));
            System.out.println("-".repeat(50));
            for (Product p : results) {
                System.out.println(String.format("%-5d | %-25s | %,12d",
                        p.getId(),
                        p.getName().length() > 25 ? p.getName().substring(0, 22) + "..." : p.getName(),
                        (long) p.getPrice()));
            }
            System.out.println("\n Tìm thấy: " + results.size() + " sản phẩm");
        } catch (Exception e) {
            System.out.println("❌ Lỗi: " + e.getMessage());
        }
    }

    // ================= CẬP NHẬT SẢN PHẨM (ADMIN) =================
    public static void updateProductAdmin(Scanner sc, ProductService productService) throws Exception {
        System.out.print("\nNhập ID sản phẩm cần cập nhật: ");
        try {
            int id = Integer.parseInt(sc.nextLine().trim());
            Product p = productService.getById(id);

            if (p == null) {
                System.out.println("❌ Sản phẩm không tồn tại!");
                return;
            }

            productService.displayDetails(p);

            System.out.print("\nTên sản phẩm (Enter nếu không thay đổi): ");
            String name = sc.nextLine().trim();
            if (!name.isEmpty()) p.setName(name);

            System.out.print("Giá (Enter nếu không thay đổi): ");
            String priceStr = sc.nextLine().trim();
            if (!priceStr.isEmpty()) {
                try {
                    p.setPrice(Double.parseDouble(priceStr));
                } catch (NumberFormatException e) {
                    System.out.println("⚠️  Giá không hợp lệ, giữ nguyên");
                }
            }

            System.out.print("Số lượng kho (Enter nếu không thay đổi): ");
            String stockStr = sc.nextLine().trim();
            if (!stockStr.isEmpty()) {
                try {
                    p.setStock(Integer.parseInt(stockStr));
                } catch (NumberFormatException e) {
                    System.out.println("⚠️  Kho không hợp lệ, giữ nguyên");
                }
            }

            try {
                productService.update(p);
                System.out.println("✅ Cập nhật sản phẩm thành công!");
            } catch (Exception e) {
                System.out.println("❌ Lỗi: " + e.getMessage());
            }
        } catch (NumberFormatException e) {
            System.out.println("❌ ID sản phẩm không hợp lệ!");
        }
    }

    // ================= XÓA SẢN PHẨM (ADMIN) =================
    public static void deleteProductAdmin(Scanner sc, ProductService productService) throws Exception {
        System.out.print("\nNhập ID sản phẩm cần xóa: ");
        try {
            int id = Integer.parseInt(sc.nextLine().trim());
            Product p = productService.getById(id);

            if (p == null) {
                System.out.println("❌ Sản phẩm không tồn tại!");
                return;
            }

            System.out.println("\n⚠️  BẠN SẮP XÓA:");
            productService.displayDetails(p);

            System.out.print("\nBạn chắc chắn muốn xóa? (yes/no): ");
            String confirm = sc.nextLine().trim().toLowerCase();

            if (confirm.equals("yes")) {
                try {
                    productService.delete(id);
                    System.out.println("✅ Xóa sản phẩm thành công!");
                } catch (Exception e) {
                    System.out.println("❌ Lỗi: " + e.getMessage());
                }
            } else {
                System.out.println("⏭️  Đã hủy xóa.");
            }
        } catch (NumberFormatException e) {
            System.out.println("❌ ID sản phẩm không hợp lệ!");
        }
    }

